#version 450
layout(local_size_x = 32) in;
layout(set = 0, binding = 0) buffer O { uint o[]; } outb;
shared uint sh[1024];
void main() {
    uint lane = gl_LocalInvocationID.x;
    for (uint r = 0u; r < 32u; r++)
        sh[r * 32u + lane] = outb.o[r * 32u + lane];
    barrier();
    uint s = 0u;
    for (uint c = 0u; c < 32u; c++)
        s += sh[lane * 32u + c];
    outb.o[lane] = s;
}
